1	//! Tests for Infernal Plunge.
2	//!
3	//! Oracle: {R} Sorcery
4	//! As an additional cost to cast this spell, sacrifice a creature.
5	//! Add {R}{R}{R}.
6	
7	mod common;
8	
9	use common::*;
10	use mtg_engine::actions::Action;
11	use mtg_engine::cards::CardRegistry;
12	use mtg_engine::types::*;
13	
14	fn registry() -> CardRegistry {
15	    CardRegistry::with_all_cards()
16	}
17	
18	/// Cannot cast Infernal Plunge without a creature to sacrifice.
19	#[test]
20	fn cannot_cast_without_creature() {
21	    let reg = registry();
22	    let mut state = game_at_step(Step::PrecombatMain, P0);
23	
24	    let _plunge = castable_spell(&mut state, &reg, "Infernal Plunge", P0);
25	
26	    let actions = mtg_engine::engine::legal_actions(&state, &reg);
27	    let can_cast = actions.actions.iter().any(|a| {
28	        matches!(a, Action::CastSpell { object_id, .. } if {
29	            state.get_object(*object_id)
30	                .map(|o| o.name == "Infernal Plunge")
31	                .unwrap_or(false)
32	        })
33	    });
34	
35	    assert!(!can_cast,
36	        "Should not be able to cast Infernal Plunge without a creature to sacrifice");
37	}
38	
39	/// Can cast Infernal Plunge when controlling a creature.
40	#[test]
41	fn can_cast_with_creature() {
42	    let reg = registry();
43	    let mut state = game_at_step(Step::PrecombatMain, P0);
44	
45	    let _plunge = castable_spell(&mut state, &reg, "Infernal Plunge", P0);
46	    let _creature = ready_creature(&mut state, P0, 1, 1);
47	
48	    let actions = mtg_engine::engine::legal_actions(&state, &reg);
49	    let can_cast = actions.actions.iter().any(|a| {
50	        matches!(a, Action::CastSpell { object_id, .. } if {
51	            state.get_object(*object_id)
52	                .map(|o| o.name == "Infernal Plunge")
53	                .unwrap_or(false)
54	        })
55	    });
56	
57	    assert!(can_cast,
58	        "Should be able to cast Infernal Plunge when controlling a creature");
59	}
60	
61	/// Sacrifice happens at cast time (creature is gone before resolution).
62	#[test]
63	fn sacrifice_at_cast_time() {
64	    let reg = registry();
65	    let mut state = game_at_step(Step::PrecombatMain, P0);
66	
67	    let plunge = castable_spell(&mut state, &reg, "Infernal Plunge", P0);
68	    let creature = ready_creature(&mut state, P0, 2, 2);
69	
70	    // Cast with explicit sacrifice target.
71	    state = mtg_engine::engine::submit_action(
72	        &state,
73	        &Action::CastSpell {
74	            object_id: plunge,
75	            targets: vec![],
76	            sacrifice: Some(creature),
77	            exile_count: None, alternative_cost: None },
78	        &reg,
79	    );
80	
81	    // Creature should already be in graveyard (sacrificed at cast time).
82	    assert_eq!(state.get_object(creature).unwrap().zone, Zone::Graveyard,
83	        "Creature should be sacrificed at cast time, not resolution");
84	
85	    // Spell should be on the stack.
86	    assert_eq!(state.get_object(plunge).unwrap().zone, Zone::Stack,
87	        "Infernal Plunge should be on the stack");
88	}
89	
90	/// On resolution, adds {R}{R}{R} to mana pool.
91	#[test]
92	fn adds_three_red_mana() {
93	    let reg = registry();
94	    let mut state = game_at_step(Step::PrecombatMain, P0);
95	
96	    let plunge = castable_spell(&mut state, &reg, "Infernal Plunge", P0);
97	    let creature = ready_creature(&mut state, P0, 2, 2);
98	
99	    // Cast with explicit sacrifice target.
100	    state = mtg_engine::engine::submit_action(
101	        &state,
102	        &Action::CastSpell {
103	            object_id: plunge,
104	            targets: vec![],
105	            sacrifice: Some(creature),
106	            exile_count: None, alternative_cost: None },
107	        &reg,
108	    );
109	
110	    // Record mana before resolution (should be 0 since we spent {R} to cast).
111	    let red_before = state.get_player(P0).mana_pool.get(ManaType::Red);
112	
113	    // Resolve the spell.
114	    mtg_engine::stack::resolve_top_of_stack(&mut state, &reg);
115	
116	    let red_after = state.get_player(P0).mana_pool.get(ManaType::Red);
117	    assert_eq!(red_after - red_before, 3,
118	        "Infernal Plunge should add RRR on resolution");
119	}
120	
121	/// Legal actions show one CastSpell per eligible creature to sacrifice.
122	#[test]
123	fn one_action_per_sacrifice_target() {
124	    let reg = registry();
125	    let mut state = game_at_step(Step::PrecombatMain, P0);
126	
127	    let _plunge = castable_spell(&mut state, &reg, "Infernal Plunge", P0);
128	    let creature_a = ready_creature(&mut state, P0, 1, 1);
129	    let creature_b = ready_creature(&mut state, P0, 3, 3);
130	
131	    let actions = mtg_engine::engine::legal_actions(&state, &reg);
132	    let plunge_actions: Vec<_> = actions.actions.iter().filter(|a| {
133	        if let Action::CastSpell { object_id, sacrifice, .. } = a {
134	            state.get_object(*object_id)
135	                .map(|o| o.name == "Infernal Plunge")
136	                .unwrap_or(false)
137	            && sacrifice.is_some()
138	        } else {
139	            false
140	        }
141	    }).collect();
142	
143	    assert_eq!(plunge_actions.len(), 2,
144	        "Should have one CastSpell action per eligible creature (got {})", plunge_actions.len());
145	
146	    // Both creatures should be represented as sacrifice options.
147	    let sac_ids: Vec<_> = plunge_actions.iter().filter_map(|a| {
148	        if let Action::CastSpell { sacrifice, .. } = a {
149	            *sacrifice
150	        } else {
151	            None
152	        }
153	    }).collect();
